sys_script.script:
(function createRetentionOnOnboard(current, previous) {
    // 1. Create the Retention Case record
    var retCase = new GlideRecord('x_2023506_german_1_ret_case');
    retCase.initialize();
    retCase.setValue('u_imm_case', current.getUniqueValue());
    retCase.setValue('u_candidate_name', current.getValue('u_candidate_name'));
    retCase.setValue('u_candidate_email', current.getValue('u_candidate_email'));
    retCase.setValue('u_retention_status', 'active');

    var today = new GlideDateTime();
    retCase.setValue('u_arrival_date', today.getLocalDate().toString());

    var retCaseId = retCase.insert();

    if (!retCaseId) {
        gs.error('Failed to create Retention Case for Immigration Case: ' + current.getValue('number'));
        return;
    }

    // 2. Create four milestone check-in records
    var milestones = [
        { milestone: '30_days', days: 30 },
        { milestone: '60_days', days: 60 },
        { milestone: '90_days', days: 90 },
        { milestone: '150_days', days: 150 }
    ];

    for (var i = 0; i < milestones.length; i++) {
        var checkin = new GlideRecord('x_2023506_german_1_ret_chkin');
        checkin.initialize();
        checkin.setValue('u_retention_case', retCaseId);
        checkin.setValue('u_milestone', milestones[i].milestone);
        checkin.setValue('u_status', 'scheduled');
        checkin.setValue('u_needs_intervention', false);

        var dueDate = new GlideDateTime();
        dueDate.addDaysLocalTime(milestones[i].days);
        checkin.setValue('u_due_date', dueDate.getLocalDate().toString());

        checkin.insert();
    }

    // 3. Add work note to the Immigration Case
    current.work_notes = 'Post-arrival retention monitoring initiated. Retention Case created with check-in milestones at Day 30, 60, 90, and 150.';
    current.update();

    gs.info('Retention Case created for ' + current.getValue('u_candidate_name') + ' with 4 milestone check-ins.');
})(current, previous);
